  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  Pie,
  PieChart,
  PolarAngleAxis,
  PolarGrid,
  PolarRadiusAxis,
  Radar,
  RadarChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  Tooltip,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import {
  ANALYTICS,
  CHANNEL_COMPARE,
  HEADLINE,
  INDUSTRY_GROUP_BILL,
  MARKETING_BILL_TREND,
  PRICE_PATH,
  PRIMARY_FACTOR_BILL,
  PRODUCT_FARM_SHARES,
  SOURCE_NOTE,
} from "@/data/farm-share-of-the-food-dollar-2026-data";

type Panel =
  | "marketing-trend"
  | "product-ladder"
  | "industry-bill"
  | "price-wedge"
  | "channel-radar";

type ChannelFocus = "all" | "at-home" | "away";
type ProductFilter = "all" | "minimal" | "moderate" | "heavy";

const COLORS = {
  farm: "#15803d",
  marketing: "#1e3a5f",
  atHome: "#0f766e",
  away: "#b45309",
  labor: "#2563eb",
  property: "#7c3aed",
  accent: "#dc2626",
  muted: "#94a3b8",
  sectors: {
    farm: "#15803d",
    midstream: "#0369a1",
    "retail-service": "#b45309",
    support: "#64748b",
  } as Record<string, string>,
  pie: ["#15803d", "#0f766e", "#0369a1", "#1e3a5f", "#b45309", "#64748b"],
};

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle ? <p className="mt-1 text-sm text-slate-500">{subtitle}</p> : null}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ControlChip({
  active,
  onClick,
  children,
}: {
  active: boolean;
  onClick: () => void;
  children: React.ReactNode;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={`rounded-lg px-3 py-1.5 text-sm font-medium transition-colors ${
        active
          ? "bg-slate-900 text-white"
          : "bg-slate-100 text-slate-700 hover:bg-slate-200"
      }`}
    >
      {children}
    </button>
  );
}

