            </ControlChip>
            <ControlChip
              active={channelFocus === "away"}
              onClick={() => setChannelFocus("away")}
            >
              Away from home
            </ControlChip>
          </>
        ) : null}
        {panel === "product-ladder" ? (
          <>
            <ControlChip
