                />
                <Tooltip
                  formatter={(value: number) => [`${value.toFixed(1)}??`, "Farm share"]}
                />
                <Bar dataKey="farmShareCents" name="Farm share" radius={[0, 4, 4, 0]}>
                  {productData.map((row) => (
                    <Cell
                      key={row.id}
                      fill={
                        row.id === "all-at-home"
                          ? COLORS.accent
                          : row.processingIntensity === "minimal"
                            ? COLORS.farm
                            : row.processingIntensity === "moderate"
                              ? COLORS.atHome
