                      `${value.toFixed(1)}`,
                      name,
                    ]}
                    labelFormatter={(_, payload) =>
                      payload?.[0]?.payload?.year
                        ? `Year ${payload[0].payload.year}`
                        : ""
                    }
                  />
                  <Scatter data={priceScatter} fill={COLORS.farm}>
                    {priceScatter.map((p) => (
                      <Cell
                        key={p.year}
